fn walk(base:&Path,p:&Path,names:&mut Vec<String>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){walk(base,&p,names)}else if e.file_type().unwrap().is_file(){names.push(p.strip_prefix(base).unwrap().to_str().unwrap().into());}}}
