    let mut inherited_masks=BTreeMap::new();for(k,expected)in[("G1-stream",2u64),("G2-original",6)]{let off=&cg["rows"][format!("OFF-{k}")];let on=&cg["rows"][format!("ON-{k}")];let b=off["mnemonics"]["vpcmpnleuq"].as_u64().unwrap_or(0);let n=on["mnemonics"]["vpcmpnleuq"].as_u64().unwrap_or(0);assert_eq!(n-b,expected);assert_eq!(off["IFMA_sites"],on["IFMA_sites"]);assert_eq!(on["VPMULLQ_sites"],0);inherited_masks.insert(k,json!({"original_unsigned_high_compares":b,"new_unsigned_high_compares":n,"new_repair_checks":n-b,"multiply_counts_unchanged":true}));}
