    let mut agg=String::new();for k in["G1","G2","ALL"]{let b=&a["aggregates"][format!("{k}/OFF")];let n=&a["aggregates"][format!("{k}/frozen")];writeln!(agg,"|{k}|{:.9} [{:.9}, {:.9}]|{}|{:.9} [{:.9}, {:.9}]|{}|",f(&b["median"]),f(&b["low"]),f(&b["high"]),b["wins"],f(&n["median"]),f(&n["low"]),f(&n["high"]),n["wins"]).unwrap();}
