    let mut m5=String::new();for(shape,t,cpu,metal)in[("1x2",8.040649245,37.,24.),("2x2",11.149096784,59.,30.),("4x2",16.069415294,109.,48.),("8x2",24.131177863,189.,74.),("12x2",33.940627784,284.,101.),("16x2",40.164083059,335.,124.),("24x2",66.187704392,528.,176.),("merge24x1",65.361571353,507.,175.)]{writeln!(m5,"|{shape}|{t:.6}|{cpu:.0}|{metal:.0}|{:.3}x|{:.3}x|{:.1}|",cpu/t,metal/t,cpu/10.).unwrap();}
