        for s in steps{for n in["command.json","exit.json","stdout.log","stderr.log"]{texts.insert(format!("inherited-OFF/{root}/{s}/{n}"),fs::read_to_string(format!("{C}/{root}/{s}/{n}")).unwrap());}}
